contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs to try opening positions for an account
    function run(address account, uint256 amountWhole, bool openMake) public payable {
        // amountWhole is interpreted as an integer amount in whole units; convert to UFixed18 by *1 (contract expects UFixed18 via external ABI)
        // We cannot construct UFixed18 in test; instead pass uint and rely on ABI encoding of the custom type (it is alias to uint256), so use amountWhole directly.
        require(account != address(0), "pre: nonzero account");

        // Read latestVersion before the mutating call
        uint256 beforeLatest = c.latestVersion();

        bool reverted;
        // Try calling either openMakeFor or openTakeFor and catch reverts
        if (openMake) {
            try c.openMakeFor(account, UFixed18.wrap(amountWhole)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amountWhole)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read latestVersion after the call
        uint256 afterLatest = c.latestVersion();

        // Assert general rule: if call reverted then latestVersion unchanged; if it succeeded then latestVersion is >= beforeLatest
        // (succeeded should not decrease latestVersion). This is a general invariant about versions advancing only on success.
        assert(reverted ? afterLatest == beforeLatest : afterLatest >= beforeLatest);
    }

    receive() external payable {}
 }

