    // We test relation between inputs to openMakeFor/openTakeFor and the computed position fee observable via behavior:
    // Because collateral.settleAccount is an external call to controller().collateral(), we cannot observe it directly.
    // Instead we observe that for zero amount, both openMakeFor/openTakeFor must not revert and the position remains such that
    // the maintenanceNext and maintenance callers are consistent. However those are complex.
    // Instead we assert a pure relation: if amount == 0 then calling openMakeFor/openTakeFor does not change latestVersion() nor emit fees — we check latestVersion unchanged.

    // Single public test function taking parameters to invoke either openMakeFor or openTakeFor
    function run(bool doMake, address account, uint256 amount) public payable {
        require(account != address(0));
        // read before state
        uint256 beforeLatest = c.latestVersion();

        // call the chosen function with amount packed as UFixed18: UFixed18 is uint256 scaled by 1e18 in library, but public API expects UFixed18 type.
        // Solidity cannot construct user-defined value types directly here; but UFixed18 underlying is uint256 so we pass amount as that type by explicit conversion.
        // However external call will accept uint256 for UFixed18 parameter.

        bool reverted;
        if (doMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: if amount == 0 then the operation must not revert and must not advance latestVersion
        // (opening a zero-sized position should be a no-op on versioning and accepted).
        assert((amount != 0) || (!reverted && c.latestVersion() == beforeLatest));
    }

    // receive to accept ETH if needed
    receive() external payable {}
}

