contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry exercising openMakeFor/openTakeFor with a choice flag
    // params:
    // - account: target account to open for
    // - amount: amount to open (UFixed18 encoded as uint256)
    // - isMake: whether to call openMakeFor (true) or openTakeFor (false)
    function run(address account, uint256 amount, bool isMake) public payable {
        require(account != address(0));
        // read pre-state
        uint256 globalBefore = c.latestVersion();
        uint256 accBefore = c.latestVersion(account);

        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After-call observations
        uint256 globalAfter = c.latestVersion();
        uint256 accAfter = c.latestVersion(account);
        // We also can read the account's pre to inspect its oracleVersion
        // But pre(address) returns a struct PrePosition; Solidity allows reading nested fields only via the tuple returned.
        // Call pre(account) and examine its oracleVersion
        (uint256 preOracleVersion,,) = c.pre(account);

        // General rule asserted:
        // If the call reverted, nothing required. If it did not revert, then either the account's latestVersion increased
        // (indicating settlement advanced for that account), or the account has a pre with oracleVersion equal to the global latestVersion (i.e., the open created a pending pre at current version).
        assert(reverted || (accAfter >= accBefore && (accAfter > accBefore || preOracleVersion == globalAfter)));
    }

    // Minimal wrappers to satisfy types for UFixed18 return in tuple deconstruction
    receive() external payable {}
}

