    // Attempt to openMakeFor then closeMakeFor for an account and amount.
    // If both calls succeed, assert that maintenanceNext(account) after the operations
    // is less-than-or-equal-to maintenance(account) observed before the operations.
    // If either call reverted, assert that at least one revert happened (we capture revert flags)
    // and still reach the single assert by relating revert behavior to the captured flags.
    function run(address account, UFixed18 amount) public payable {
        require(true);

        // Read maintenance before any state changes (UFixed18 is a value type returned by view)
        UFixed18 beforeMaintenance = c.maintenance(account);

        bool openReverted;
        try c.openMakeFor(account, amount) {
            openReverted = false;
        } catch {
            openReverted = true;
        }

        bool closeReverted;
        try c.closeMakeFor(account, amount) {
            closeReverted = false;
        } catch {
            closeReverted = true;
        }

        UFixed18 afterMaintenanceNext = c.maintenanceNext(account);

        // We must have exactly one assert at the end. Construct a condition that
        // expresses the intended property: if neither call reverted, then afterMaintenanceNext <= beforeMaintenance;
        // otherwise (some revert) the condition is simply that at least one revert occurred (which is true),
        // so overall the assert depends on observable values and revert flags.
        bool nonRevertedProperty;
        if (!openReverted && !closeReverted) {
            // Use public view truncate() to compare since UFixed18 has no direct operators here.
            // maintenanceNext <= maintenance  <=> afterMaintenanceNext.lte(beforeMaintenance)
            nonRevertedProperty = afterMaintenanceNext.lte(beforeMaintenance);
        } else {
            nonRevertedProperty = (openReverted || closeReverted);
        }

        assert(nonRevertedProperty);
    }

    receive() external payable {}
}

